package au.aumanet.app;

import android.content.Context;
import android.os.SystemClock;
import com.getcapacitor.JSObject;
import org.json.*;
import javax.net.ssl.*;
import java.io.*;
import java.net.*;
import java.security.cert.X509Certificate;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.BooleanSupplier;

/** Explicit, native-owned phone-to-phone benchmark on the approved group LAN.
 * Endpoint advertisements never authorize a connection. Each socket uses the
 * existing pinned device certificate and exact original group/control ticket.
 * No cellular/network default, internet-donation, GPS start or consent adoption. */
final class LinkBenchmarkController {
    static final long ARM_MS=15*60*1000L;
    private static volatile LinkBenchmarkController instance;
    static synchronized LinkBenchmarkController get(Context context)throws Exception{if(android.os.Build.VERSION.SDK_INT<29)throw new IllegalStateException("Link tests need Android 10 or later");if(instance==null)instance=new LinkBenchmarkController(context.getApplicationContext());return instance;}
    static LinkBenchmarkController peek(){return instance;}
    interface Reply{void done(JSObject state);void failed(String code);}
    private final Context context;private final GroupSession group;
    final String process=UUID.randomUUID().toString();
    private final AtomicLong sequence=new AtomicLong(),armRequests=new AtomicLong();
    static final class Preparation{final InternetSharingScope scope;final long number;Preparation(InternetSharingScope scope,long number){this.scope=scope;this.number=number;}}
    Preparation prepareArm(){InternetSharingScope scope=group.internetScope();if(scope==null||arm!=null)throw new IllegalStateException();return new Preparation(scope,armRequests.incrementAndGet());}
    void cancelPreparation(Preparation expected){if(expected!=null)armRequests.compareAndSet(expected.number,expected.number+1);}
    private final ScheduledThreadPoolExecutor actor=new ScheduledThreadPoolExecutor(1);
    private final Semaphore commands=new Semaphore(8),healthPending=new Semaphore(1);
    private final ThreadPoolExecutor io=new ThreadPoolExecutor(2,2,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<>(2),r->{Thread t=new Thread(r,"AuMaNET-link-test");t.setDaemon(true);return t;});
    private final GroupSocketBudget sockets=new GroupSocketBudget(6,2);
    private final LinkBenchmarkHistory history;
    private volatile Arm arm;private volatile Test test;private volatile JSONObject lastResult;
    private volatile String state="idle",error="";private volatile long phaseBytes,phaseElapsed;
    private final Map<String,Offer> offers=new ConcurrentHashMap<>();private final Set<String> seen=new LinkedHashSet<>();
    private static final class Offer{final String peer,id,address;final int port;final long at;final InternetSharingScope scope;final BooleanSupplier live;Offer(String p,String id,String address,int port,long at,InternetSharingScope scope,BooleanSupplier live){peer=p;this.id=id;this.address=address;this.port=port;this.at=at;this.scope=scope;this.live=live;}}
    private static final class Pending{final GroupSocketBudget.Lease lease;final long at=SystemClock.elapsedRealtime();Pending(GroupSocketBudget.Lease lease){this.lease=lease;}}
    private static final class Arm{final String id=GroupWire.random(16);final InternetSharingScope scope;final long deadline=SystemClock.elapsedRealtime()+ARM_MS;final AtomicBoolean active=new AtomicBoolean(true);final Map<SSLSocket,Pending> incoming=new ConcurrentHashMap<>();volatile SSLServerSocket server;volatile GroupSocketBudget.Lease listener;Arm(InternetSharingScope scope){this.scope=scope;}}
    private static final class Test{final String id,peer;final Arm arm;final boolean initiator,comparison;final BooleanSupplier peerGuard;final long startedAt=System.currentTimeMillis(),created=SystemClock.elapsedRealtime();final AtomicBoolean live=new AtomicBoolean(true),finished=new AtomicBoolean();volatile long deadline,bytes,elapsed;volatile String phase="",diagnosticStage="CREATED";volatile Socket raw;volatile SSLSocket secure;volatile GroupSocketBudget.Lease lease;volatile boolean cancelled,quiet;volatile JSONObject upload,download,metadata;Test(String id,String peer,Arm arm,boolean initiator,BooleanSupplier guard){this(id,peer,arm,initiator,guard,false);}Test(String id,String peer,Arm arm,boolean initiator,BooleanSupplier guard,boolean comparison){this.comparison=comparison;this.id=id;this.peer=peer;this.arm=arm;this.initiator=initiator;peerGuard=guard;}}
    private LinkBenchmarkController(Context context)throws Exception{
        this.context=context;group=GroupSession.get(context);LinkBenchmarkVoice.install();history=new LinkBenchmarkHistory(new File(context.getNoBackupFilesDir(),"link-benchmark-results-v1.json"));
        actor.setRemoveOnCancelPolicy(true);actor.scheduleAtFixedRate(()->{if(healthPending.tryAcquire())try{health();}finally{healthPending.release();}},100,100,TimeUnit.MILLISECONDS);
    }
    void dispatch(java.util.concurrent.Callable<JSObject> command,Reply reply){if(!commands.tryAcquire()){reply.failed("LINK_TEST_BUSY");return;}actor.execute(()->{try{reply.done(command.call());}catch(Exception rejected){reply.failed("LINK_TEST_REQUEST_REJECTED");}finally{commands.release();}});}
    private boolean armLive(Arm a){return a!=null&&arm==a&&a.active.get()&&SystemClock.elapsedRealtime()<a.deadline&&group.internetCurrent(a.scope);}
    private boolean testLive(Test t){long now=SystemClock.elapsedRealtime();return t!=null&&test==t&&t.live.get()&&armLive(t.arm)&&t.peerGuard.getAsBoolean()&&!internetActive()&&now>=t.created&&(t.deadline==0?now-t.created<20000:now<t.deadline)&&(!t.quiet||LinkBenchmarkTraffic.owns(t));}
    private static boolean internetActive(){InternetSharingController c=InternetSharingController.peek();return c!=null&&c.active();}
    private void health(){try{Arm a=arm;if(a!=null&&(!armLive(a)||!LinkBenchmarkService.notificationsAllowed(context))){retireArm(a,"LINK_TEST_ARM_ENDED");return;}if(a!=null){long now=SystemClock.elapsedRealtime();for(Map.Entry<SSLSocket,Pending> entry:a.incoming.entrySet())if(now-entry.getValue().at>=12000&&a.incoming.remove(entry.getKey(),entry.getValue()))entry.getValue().lease.closeAsync(entry.getKey(),now);}Test t=test;if(t!=null&&!testLive(t)){end(t,t.cancelled?"LINK_TEST_CANCELLED":"LINK_TEST_CONNECTION_ENDED");}}catch(Exception unavailable){Test t=test;if(t!=null)end(t,"LINK_TEST_CONNECTION_ENDED");}}
    JSObject arm(JSONObject request,Preparation expected)throws Exception{
        if(!"arm-link-test-for-15-minutes".equals(request.optString("acknowledgement"))||expected==null||armRequests.get()!=expected.number||!group.internetCurrent(expected.scope)||arm!=null||internetActive()||!history.available())throw new IllegalStateException();
        InternetSharingScope scope=expected.scope;Arm next=new Arm(scope);synchronized(this){if(armRequests.get()!=expected.number||arm!=null)throw new IllegalStateException();arm=next;}state="preparing";error="";sequence.incrementAndGet();
        try{LinkBenchmarkService.start(context,next.id);io.execute(()->listen(next));}catch(Exception failed){retireArm(next,"LINK_TEST_SERVICE_UNAVAILABLE");throw failed;}return snapshot();
    }
    private void listen(Arm a){GroupSocketBudget.Lease reservation=null;try{
        reservation=sockets.reserve();if(reservation==null)throw new IOException();
        SSLContext tls=group.internetIdentity(a.scope).context(pin->armLive(a)&&a.scope.approved.contains(pin)&&!pin.equals(a.scope.self));
        SSLServerSocket server=(SSLServerSocket)tls.getServerSocketFactory().createServerSocket();synchronized(a){if(!armLive(a)){reservation.closeAsync(server,SystemClock.elapsedRealtime());return;}a.server=server;a.listener=reservation;}server.setReuseAddress(true);server.setNeedClientAuth(true);server.bind(new InetSocketAddress(InetAddress.getByName(a.scope.address),0),1);server.setSoTimeout(500);if(!armLive(a))throw new IOException();state="armed";sequence.incrementAndGet();
        while(armLive(a)){GroupSocketBudget.Lease incoming=sockets.reserve();if(incoming==null)throw new IOException();SSLSocket socket=null;try{socket=(SSLSocket)server.accept();synchronized(a){if(!armLive(a)||test!=null){incoming.closeAsync(socket,SystemClock.elapsedRealtime());continue;}a.incoming.put(socket,new Pending(incoming));}final SSLSocket accepted=socket;io.execute(()->accept(a,accepted,incoming));}catch(SocketTimeoutException waiting){incoming.unused();}catch(Exception failed){if(socket==null)incoming.unused();else{a.incoming.remove(socket);incoming.closeAsync(socket,SystemClock.elapsedRealtime());}if(!armLive(a))break;}}
    }catch(Exception failed){if(arm==a)retireArm(a,"LINK_TEST_LISTENER_UNAVAILABLE");}finally{if(reservation!=null){if(a.server!=null)reservation.closeAsync(a.server,SystemClock.elapsedRealtime());else reservation.unused();}}}
    private void accept(Arm a,SSLSocket socket,GroupSocketBudget.Lease lease){Test t=null;try{
        socket.setSendBufferSize(32768);socket.setReceiveBufferSize(32768);socket.setSoTimeout(12000);socket.startHandshake();String peer=GroupIdentity.fingerprint((X509Certificate)socket.getSession().getPeerCertificates()[0]);BooleanSupplier guard=group.internetPeerGuard(a.scope,peer);if(!armLive(a)||!guard.getAsBoolean()||!history.available())throw new IOException();DataInputStream in=new DataInputStream(socket.getInputStream());DataOutputStream out=new DataOutputStream(socket.getOutputStream());JSONObject hello=LinkBenchmarkWire.json(in);String id=LinkBenchmarkWire.hello(hello,a.scope.group,a.scope.epoch,a.scope.self,peer,a.id);
        if(!LinkBenchmarkService.ready(a.id))throw new IOException();
        synchronized(a){synchronized(this){Pending pending=a.incoming.remove(socket);if(pending==null||SystemClock.elapsedRealtime()-pending.at>=12000||test!=null||!armLive(a)||seen.contains(id))throw new IOException();seen.add(id);while(seen.size()>128)seen.remove(seen.iterator().next());t=new Test(id,peer,a,false,guard,"channel-comparison".equals(hello.optString("testProfile")));t.secure=socket;t.lease=lease;test=t;}}
        run(t,in,out);
    }catch(Exception failure){if(t!=null){diagnostic(t,failure);end(t,"LINK_TEST_TRANSPORT_INTERRUPTED");}}finally{a.incoming.remove(socket);if(t==null)lease.closeAsync(socket,SystemClock.elapsedRealtime());}}
    JSObject start(JSONObject request)throws Exception{
        Arm a=arm;String peer=GroupNameMetadata.string(request,"peerId");String profile=request.optString("testProfile","standard");if(!profile.equals("standard")&&!profile.equals("channel-comparison"))throw new IllegalArgumentException();if(!"pause-traffic-and-test-link".equals(request.optString("acknowledgement"))||!process.equals(request.optString("expectedProcessId"))||!armLive(a)||!a.id.equals(request.optString("expectedArmId"))||!LinkBenchmarkService.ready(a.id)||test!=null||LinkBenchmarkTraffic.active()||internetActive()||!history.available()||!a.scope.approved.contains(peer)||peer.equals(a.scope.self))throw new IllegalStateException();Offer offer=offers.get(peer);if(!offerLive(offer,a.scope))throw new IllegalStateException();BooleanSupplier guard=group.internetPeerGuard(a.scope,peer);if(!guard.getAsBoolean())throw new IllegalStateException();Test next=new Test(GroupWire.random(16),peer,a,true,guard,profile.equals("channel-comparison"));synchronized(this){if(test!=null)throw new IllegalStateException();test=next;}state="preparing";error="";sequence.incrementAndGet();try{io.execute(()->connect(next,offer));}catch(RejectedExecutionException busy){end(next,"LINK_TEST_BUSY");throw busy;}return snapshot();
    }
    private void connect(Test t,Offer offer){try{t.diagnosticStage="CONNECT";
        GroupSocketBudget.Lease lease=sockets.reserve();if(lease==null)throw new IOException();Socket raw;try{raw=t.arm.scope.network.getSocketFactory().createSocket();}catch(Exception failed){lease.unused();throw failed;}synchronized(t){if(!t.live.get()){lease.closeAsync(raw,SystemClock.elapsedRealtime());return;}t.lease=lease;t.raw=raw;}raw.setSendBufferSize(32768);raw.setReceiveBufferSize(32768);if(!armLive(t.arm)||!t.peerGuard.getAsBoolean())throw new IOException();raw.connect(new InetSocketAddress(offer.address,offer.port),5000);raw.setSoTimeout(12000);
        SSLContext tls=group.internetIdentity(t.arm.scope).context(pin->pin.equals(t.peer)&&armLive(t.arm)&&t.peerGuard.getAsBoolean());SSLSocket secure=(SSLSocket)tls.getSocketFactory().createSocket(raw,offer.address,offer.port,true);synchronized(t){if(!t.live.get()){lease.closeAsync(raw,secure,SystemClock.elapsedRealtime());return;}t.secure=secure;}t.diagnosticStage="TLS";secure.startHandshake();if(!t.peer.equals(GroupIdentity.fingerprint((X509Certificate)secure.getSession().getPeerCertificates()[0]))||!t.peerGuard.getAsBoolean())throw new IOException();DataInputStream in=new DataInputStream(secure.getInputStream());DataOutputStream out=new DataOutputStream(secure.getOutputStream());
        t.diagnosticStage="HELLO";JSONObject hello=new JSONObject().put("schema","aumanet.link-test.v1").put("groupId",t.arm.scope.group).put("epoch",t.arm.scope.epoch).put("from",t.arm.scope.self).put("to",t.peer).put("armId",offer.id).put("testId",t.id);if(t.comparison)hello.put("testProfile","channel-comparison");LinkBenchmarkWire.json(out,hello);run(t,in,out);
    }catch(Exception failed){diagnostic(t,failed);end(t,"LINK_TEST_TRANSPORT_INTERRUPTED");}}
    private void run(Test t,DataInputStream in,DataOutputStream out)throws Exception{
        t.secure.setSoTimeout(20000);t.diagnosticStage="QUIET";if(!testLive(t)||internetActive()||!LinkBenchmarkTraffic.acquireWhenAvailable(t,()->testLive(t)&&!internetActive(),2000))throw new IOException();t.quiet=true;if(!testLive(t)){LinkBenchmarkTraffic.release(t);throw new IOException();}state="preparing";t.diagnosticStage="RADIO_METADATA";refreshRadioMetadata(t.arm.scope);t.metadata=group.benchmarkMetadata(t.arm.scope,t.peer);
        t.diagnosticStage="READY";if(t.initiator){JSONObject ready=LinkBenchmarkWire.json(in);if(!t.id.equals(ready.optString("ready")))throw new IOException();LinkBenchmarkWire.json(out,new JSONObject().put("begin",t.id));}else{LinkBenchmarkWire.json(out,new JSONObject().put("ready",t.id));if(!t.id.equals(LinkBenchmarkWire.json(in).optString("begin")))throw new IOException();}
        t.secure.setSoTimeout(12000);t.deadline=SystemClock.elapsedRealtime()+LinkBenchmarkWire.DEADLINE_MS;LinkBenchmarkWire.Budget budget=new LinkBenchmarkWire.Budget();
        for(String phase:new String[]{"warmup-upload","upload","warmup-download","download"}){
            if(!testLive(t))throw new IOException();boolean upload=phase.endsWith("upload"),sending=t.initiator==upload;String localPhase=t.initiator?phase:phase.replace("upload","temporary").replace("download","upload").replace("temporary","download");t.diagnosticStage="TRANSFER";t.phase=localPhase;t.bytes=t.elapsed=0;state=localPhase;phaseBytes=phaseElapsed=0;sequence.incrementAndGet();long duration=phase.startsWith("warmup")?(t.comparison?LinkBenchmarkWire.COMPARISON_WARMUP_MS:LinkBenchmarkWire.WARMUP_MS):(t.comparison?LinkBenchmarkWire.COMPARISON_MEASURE_MS:LinkBenchmarkWire.MEASURE_MS);
            LinkBenchmarkWire.Progress progress=(bytes,elapsed)->{if(test==t&&t.live.get()){t.bytes=phaseBytes=bytes;t.elapsed=phaseElapsed=elapsed;}};
            JSONObject measured=sending?LinkBenchmarkWire.send(out,in,phase,duration,budget,SystemClock::elapsedRealtime,()->testLive(t),progress):LinkBenchmarkWire.receive(in,out,phase,budget,SystemClock::elapsedRealtime,()->testLive(t),progress);
            if(!phase.startsWith("warmup")){if(sending)t.upload=measured;else t.download=measured;}
        }
        if(t.initiator){LinkBenchmarkWire.json(out,new JSONObject().put("complete",t.id));if(!t.id.equals(LinkBenchmarkWire.json(in).optString("complete")))throw new IOException();}else{if(!t.id.equals(LinkBenchmarkWire.json(in).optString("complete")))throw new IOException();LinkBenchmarkWire.json(out,new JSONObject().put("complete",t.id));}
        if(!testLive(t))throw new IOException();end(t,"");
    }
    private void diagnostic(Test t,Exception failure){android.util.Log.w("AuMaNETLinkTest","role="+(t.initiator?"initiator":"receiver")+" stage="+t.diagnosticStage+" reason="+failure.getClass().getSimpleName());}
    private void end(Test t,String code){if(!t.finished.compareAndSet(false,true))return;t.live.set(false);synchronized(t){if(t.lease!=null){if(t.secure!=null||t.raw!=null)t.lease.closeAsync(t.raw,t.secure,SystemClock.elapsedRealtime());else t.lease.unused();}}if(code.isEmpty())refreshRadioMetadata(t.arm.scope);JSONObject observedEnd=null;try{observedEnd=group.benchmarkMetadata(t.arm.scope,t.peer);}catch(Exception unavailable){}final JSONObject metadataAtEnd=observedEnd;LinkBenchmarkTraffic.release(t);
        actor.execute(()->{try{
            JSONObject result=new JSONObject().put("schema","aumanet.link-benchmark-result.v1").put("testProfile",t.comparison?"channel-comparison":"standard").put("id",t.id).put("peerId",t.peer).put("groupId",t.arm.scope.group).put("selfId",t.arm.scope.self).put("startedAt",t.startedAt).put("completedAt",Math.max(t.startedAt,System.currentTimeMillis())).put("status",code.isEmpty()?"complete":t.cancelled?"cancelled":"failed").put("path","approved-group-wifi").put("measurement","phone-to-phone-payload-goodput").put("errorCode",code).put("radioSignals",new JSONArray()).put("positions",new JSONObject()).put("locationLabel","Phone GPS separation; nodes assumed carried with phones");
            JSONObject empty=LinkBenchmarkWire.measurement(0,0,0,false);result.put("upload",t.upload==null?(t.phase.equals("upload")?LinkBenchmarkWire.measurement(t.bytes,0,Math.min(LinkBenchmarkWire.DEADLINE_MS,t.elapsed),false):empty):t.upload).put("download",t.download==null?(t.phase.equals("download")?LinkBenchmarkWire.measurement(t.bytes,t.bytes,Math.min(LinkBenchmarkWire.DEADLINE_MS,t.elapsed),false):empty):t.download);
            LinkBenchmarkMetadata.observations(result,t.metadata,metadataAtEnd);lastResult=result;
            try{history.append(result);}catch(Exception uncertain){error="LINK_TEST_HISTORY_UNAVAILABLE";}if(test==t){test=null;state=code.isEmpty()?"complete":"interrupted";if(!code.isEmpty())error=code;}sequence.incrementAndGet();
        }catch(Exception failed){error="LINK_TEST_HISTORY_UNAVAILABLE";if(test==t)test=null;}});
    }
    private void refreshRadioMetadata(InternetSharingScope scope){try{GatewayRadioSettingsController.get(context);GatewayRadioSettingsController.refreshForBenchmark(scope);}catch(Exception unavailable){/* Metadata remains absent/stale rather than blocking usable tests. */}}
    void stop(String expectedProcess,String id){if(!process.equals(expectedProcess))return;Arm a;synchronized(this){a=arm;if(a==null){if(id.isEmpty())armRequests.incrementAndGet();return;}if(!a.id.equals(id))return;armRequests.incrementAndGet();}Test t=test;if(t!=null&&t.arm==a)t.cancelled=true;retireArm(a,"LINK_TEST_CANCELLED");}
    void stopArm(String id){Arm a=arm;if(a!=null&&a.id.equals(id)){Test t=test;if(t!=null&&t.arm==a)t.cancelled=true;retireArm(a,"LINK_TEST_CANCELLED");}}
    private void retireArm(Arm a,String code){if(!a.active.compareAndSet(true,false))return;Test t;synchronized(a){t=test;for(Map.Entry<SSLSocket,Pending> entry:a.incoming.entrySet())entry.getValue().lease.closeAsync(entry.getKey(),SystemClock.elapsedRealtime());a.incoming.clear();if(a.listener!=null){if(a.server!=null)a.listener.closeAsync(a.server,SystemClock.elapsedRealtime());else a.listener.unused();}}if(t!=null&&t.arm==a)end(t,code);if(arm==a){arm=null;state="idle";error=code;sequence.incrementAndGet();}LinkBenchmarkService.finish(context,a.id);}
    JSObject snapshot()throws Exception{
        InternetSharingScope scope=group.internetScope();Arm a=arm;Test t=test;JSONArray peers=new JSONArray();for(Offer offer:offers.values())if(offerLive(offer,scope))peers.put(new JSONObject().put("peerId",offer.peer).put("armId",offer.id).put("available",true));
        JSObject value=new JSObject().put("schema","aumanet.link-benchmark.v1").put("source","device").put("processId",process).put("sequence",sequence.get()).put("available",scope!=null).put("canArm",scope!=null&&a==null&&!LinkBenchmarkTraffic.active()&&!internetActive()&&history.available()).put("armId",a==null?"":a.id).put("armed",armLive(a)).put("armRemainingMs",a==null?0:Math.max(0,a.deadline-SystemClock.elapsedRealtime())).put("state",state).put("errorCode",!history.available()?"LINK_TEST_HISTORY_UNAVAILABLE":error).put("peerId",t==null?"":t.peer).put("phaseElapsedMs",phaseElapsed).put("phaseBytes",phaseBytes).put("peers",peers).put("results",history.snapshot());if(scope!=null)value.put("scope",new JSONObject().put("groupId",scope.group).put("selfId",scope.self).put("epoch",scope.epoch));if(lastResult!=null)value.put("result",new JSONObject(lastResult.toString()));return value;
    }
    private boolean offerLive(Offer offer,InternetSharingScope scope){long age=offer==null?Long.MAX_VALUE:SystemClock.elapsedRealtime()-offer.at;return offer!=null&&scope!=null&&scope.exact(offer.scope)&&age>=0&&age<15000&&offer.live.getAsBoolean()&&scope.approved.contains(offer.peer)&&scope.online.contains(offer.peer);}
    JSONArray wire(){JSONArray list=new JSONArray();Arm a=arm;try{InternetSharingScope scope=group.internetScope();if(armLive(a)&&LinkBenchmarkService.ready(a.id)&&a.server!=null&&!a.server.isClosed())list.put(new JSONObject().put("peerId",a.scope.self).put("armId",a.id).put("port",a.server.getLocalPort()).put("address",a.scope.address));if(scope!=null&&scope.self.equals(scope.owner))for(Offer offer:offers.values())if(offerLive(offer,scope))list.put(new JSONObject().put("peerId",offer.peer).put("armId",offer.id).put("port",offer.port).put("address",offer.address));}catch(Exception invalid){}return list;}
    void received(InternetSharingScope scope,String sender,String address,JSONArray values,BooleanSupplier live){try{if(values.length()>(scope.self.equals(scope.owner)?1:5)||!live.getAsBoolean())return;for(int i=0;i<values.length();i++){JSONObject value=values.getJSONObject(i);String peer=value.getString("peerId"),id=value.getString("armId");int port=(int)LinkBenchmarkWire.integer(value,"port",65535);String host=scope.self.equals(scope.owner)?address:value.getString("address");if(peer.equals(scope.self)||!scope.approved.contains(peer)||!id.matches("[a-f0-9]{32}")||port<1||scope.self.equals(scope.owner)&&!peer.equals(sender)||!scope.self.equals(scope.owner)&&!sender.equals(scope.owner))continue;GroupWire.privateIPv4(host);byte[] selected=InetAddress.getByName(scope.address).getAddress(),candidate=InetAddress.getByName(host).getAddress();if(candidate.length!=4||candidate[0]!=selected[0]||candidate[1]!=selected[1]||candidate[2]!=selected[2])continue;BooleanSupplier peerTicket=group.internetPeerGuard(scope,peer);if(!peerTicket.getAsBoolean())continue;offers.put(peer,new Offer(peer,id,host,port,SystemClock.elapsedRealtime(),scope,()->live.getAsBoolean()&&peerTicket.getAsBoolean()));if(offers.size()>5)offers.clear();}}catch(Exception invalid){}}
    String export(String format)throws Exception{return history.export(format);}
}
